const page = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>Avani Funde Portfolio</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link href=\"https://fonts.googleapis.com/css2?family=Baloo+2:wght@600;700;800&family=Inter:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\n<link rel=\"stylesheet\" href=\"styles.css\">\n</head>\n<body>\n\n<div class=\"marquee\">\n  <div class=\"marquee-track\">\n    <span>Product Marketing &#10022; Go-To-Market &#10022; Product-Led Growth &#10022; Positioning &#10022; Growth Strategy &#10022; Product Marketing &#10022; Go-To-Market &#10022; Product-Led Growth &#10022; Positioning &#10022; Growth Strategy &#10022; </span>\n    <span>Product Marketing &#10022; Go-To-Market &#10022; Product-Led Growth &#10022; Positioning &#10022; Growth Strategy &#10022; Product Marketing &#10022; Go-To-Market &#10022; Product-Led Growth &#10022; Positioning &#10022; Growth Strategy &#10022; </span>\n  </div>\n</div>\n\n<header class=\"nav\">\n  <a href=\"index.html\" class=\"logo\">Avani Funde</a>\n  <nav class=\"nav-links\">\n    <a href=\"#about\">About</a>\n    <a href=\"#highlights\">Case Studies</a>\n    <a href=\"https://www.linkedin.com/in/avanifunde/\" target=\"_blank\" rel=\"noopener\" class=\"btn-nav\">Connect ↗</a>\n  </nav>\n</header>\n\n<main class=\"wrap\">\n\n  <section class=\"hero\">\n    <div class=\"hero-copy\">\n      <span class=\"eyebrow\">Product Marketing Manager · Growth</span>\n      <h1>Hi, I am Avani, I <span class=\"highlight\">connect the dots</span> between what we build, why the market should care, and how we grow.</h1>\n      <p class=\"hero-sub\">For 8 years, I've worked at the intersection of Product, Sales, and Growth, taking products from idea → market → adoption. Positioning, launches, GTM, activation, acquisition, experiments. If it helps turn a product bet into measurable growth, I'm probably in it.</p>\n      <div class=\"hero-actions\">\n        <a href=\"#highlights\" class=\"btn-primary\">See Case Studies →</a>\n        <a href=\"https://www.linkedin.com/in/avanifunde/\" target=\"_blank\" rel=\"noopener\" class=\"btn-secondary\">Connect on LinkedIn</a>\n      </div>\n    </div>\n    <div class=\"hero-visual\">\n      <span class=\"spark spark-1\">✦</span>\n      <span class=\"spark spark-2\">✦</span>\n      <div class=\"photo-frame\">\n        <img src=\"images/avani.jpg\" alt=\"Avani Funde\" class=\"hero-photo\" onerror=\"this.style.display='none'; this.nextElementSibling.style.display='flex';\">\n        <div class=\"photo-placeholder\">📷<span>Drop your photo at<br><code>images/avani.jpg</code></span></div>\n      </div>\n    </div>\n  </section>\n\n  <section class=\"about\" id=\"about\">\n    <h2>8 years across B2B SaaS, AI, and product-led growth.</h2>\n    <div class=\"about-bio\">\n      <p class=\"bio\">I'm a Product Marketing Manager with experience across B2B SaaS and AI, most recently at Vieu and Avoma, and earlier at Graas (Shoptimize). I've worked in environments where PMM goes well beyond launches: getting close to customers, shaping positioning, building GTM from scratch, enabling Sales, improving activation, and experimenting with what drives growth.</p>\n      <p class=\"bio\">I'm naturally a hands-on marketer. I like digging into product data, listening to customer calls, testing a hypothesis, building the thing, and seeing whether it actually moves a metric.</p>\n      <p class=\"bio\">My background sits at the intersection of technical and creative: a Bachelor's in Electronics &amp; Telecommunications Engineering and a Master's in Marketing, New Media &amp; Communications from Bologna Business School, Italy. That combination has shaped how I work: understand the product deeply, simplify the complexity, and make the story matter.</p>\n    </div>\n  </section>\n\n  <section class=\"highlights\" id=\"highlights\">\n    <h2>Select Project Highlights</h2>\n    <div class=\"highlight-grid\">\n      <div class=\"highlight-card\">\n        <span class=\"hl-tag\">Product Launch &amp; Adoption</span>\n        <p class=\"hl-desc\">Led GTM and adoption for <strong>Vieu's</strong> new AI experience and Chrome Extension, using PostHog to understand and improve engagement.</p>\n        <div class=\"hl-metrics\">\n          <span class=\"hl-metric\">+7% Weekly Users</span>\n          <span class=\"hl-metric\">+26% Extension MAU</span>\n        </div>\n      </div>\n      <div class=\"highlight-card\">\n        <span class=\"hl-tag\">Go-to-Market</span>\n        <p class=\"hl-desc\">Took <strong>Avoma's</strong> AI capabilities to market across positioning, messaging, launch campaigns, in-app, and customer-facing channels.</p>\n        <div class=\"hl-metrics\">\n          <span class=\"hl-metric\">+23% Feature Adoption</span>\n          <span class=\"hl-metric\">+3.4% Trial-to-Paid</span>\n        </div>\n      </div>\n      <div class=\"highlight-card\">\n        <span class=\"hl-tag\">Product-Led Growth</span>\n        <p class=\"hl-desc\">Partnered with Product at <strong>Avoma</strong> to simplify onboarding, remove friction, and shorten the path from signup to first value.</p>\n        <div class=\"hl-metrics\">\n          <span class=\"hl-metric\">+11% Product Sign-ups</span>\n          <span class=\"hl-metric\">7 → 3 Screens</span>\n        </div>\n      </div>\n      <div class=\"highlight-card\">\n        <span class=\"hl-tag\">Product Positioning</span>\n        <p class=\"hl-desc\">Localized <strong>Graas (Shoptimize)</strong> positioning and digital experiences to take the same product across three distinct markets.</p>\n        <div class=\"hl-metrics\">\n          <span class=\"hl-metric\">3 Markets Launched</span>\n          <span class=\"hl-metric\">50% Organic Traffic</span>\n        </div>\n      </div>\n      <div class=\"highlight-card\">\n        <span class=\"hl-tag\">Product Analytics</span>\n        <p class=\"hl-desc\">Used product and behavioral data across <strong>Vieu, Avoma, and Graas</strong> to understand funnels, uncover friction, and inform product and growth decisions.</p>\n        <div class=\"hl-metrics\">\n          <span class=\"hl-metric\">PostHog</span>\n          <span class=\"hl-metric\">Amplitude</span>\n          <span class=\"hl-metric\">Microsoft Clarity</span>\n          <span class=\"hl-metric\">Google Analytics</span>\n          <span class=\"hl-metric\">Google Sheets ♥</span>\n        </div>\n      </div>\n      <div class=\"highlight-card\">\n        <span class=\"hl-tag\">Content &amp; Engagement</span>\n        <p class=\"hl-desc\">Built customer education and ongoing engagement programs for <strong>Avoma + Vieu</strong>, from self-serve Help Centers to monthly product newsletters.</p>\n        <div class=\"hl-metrics\">\n          <span class=\"hl-metric\">2 Help Centers</span>\n          <span class=\"hl-metric\">Monthly Product Newsletters</span>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <section class=\"social-proof\">\n    <h2>Let's connect</h2>\n    <p>See the full career history and network on LinkedIn.</p>\n    <a href=\"https://www.linkedin.com/in/avanifunde/\" target=\"_blank\" rel=\"noopener\" class=\"btn-primary linkedin-btn\">View LinkedIn Profile ↗</a>\n  </section>\n\n</main>\n\n<footer class=\"footer wrap\">\n  <div>\n    <p class=\"footer-name\">Avani Funde</p>\n    <p>Product Marketing Manager (Growth)</p>\n  </div>\n  <div class=\"footer-links\">\n    <a href=\"mailto:avanifunde@gmail.com\">avanifunde@gmail.com</a>\n    <a href=\"https://www.linkedin.com/in/avanifunde/\" target=\"_blank\" rel=\"noopener\">LinkedIn</a>\n    <a href=\"#highlights\">Case Studies</a>\n  </div>\n  <p class=\"footer-copy\">© 2026 Avani Funde.</p>\n</footer>\n\n</body>\n</html>\n";
const styles = "/* ===== Design tokens ===== */\n:root {\n  --cream: #FBF1DD;\n  --cream-2: #F5E8CC;\n  --black: #14120E;\n  --yellow: #F4E04D;\n  --yellow-dark: #E3CE22;\n  --muted: #5B5648;\n  --white: #FFFFFF;\n  --border: rgba(20, 18, 14, 0.12);\n  --radius: 20px;\n  --shadow: 0 10px 30px rgba(20, 18, 14, 0.08);\n}\n\n* { box-sizing: border-box; }\n\nhtml { scroll-behavior: smooth; }\n\nbody {\n  margin: 0;\n  background: var(--cream);\n  color: var(--black);\n  font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;\n  -webkit-font-smoothing: antialiased;\n}\n\nh1, h2, h3, h4 {\n  font-family: 'Baloo 2', 'Inter', sans-serif;\n  font-weight: 700;\n  margin: 0;\n  letter-spacing: -0.01em;\n}\n\np { margin: 0; line-height: 1.6; }\n\na { color: inherit; text-decoration: none; }\n\nimg { max-width: 100%; display: block; }\n\n.wrap {\n  max-width: 1160px;\n  margin: 0 auto;\n  padding: 0 32px;\n}\n\n/* ===== Marquee ===== */\n.marquee {\n  background: var(--black);\n  color: var(--cream);\n  overflow: hidden;\n  white-space: nowrap;\n  padding: 12px 0;\n}\n.marquee-track {\n  display: inline-flex;\n  animation: scroll-left 22s linear infinite;\n}\n.marquee-track span {\n  padding-right: 8px;\n  font-size: 14px;\n  font-weight: 600;\n  letter-spacing: 0.04em;\n  text-transform: uppercase;\n}\n@keyframes scroll-left {\n  from { transform: translateX(0); }\n  to { transform: translateX(-50%); }\n}\n\n/* ===== Nav ===== */\n.nav {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  max-width: 1160px;\n  margin: 0 auto;\n  padding: 24px 32px 8px;\n}\n.logo {\n  font-family: 'Baloo 2', sans-serif;\n  font-weight: 700;\n  font-size: 30px;\n}\n.nav-links {\n  display: flex;\n  align-items: center;\n  gap: 28px;\n  font-weight: 600;\n  font-size: 15px;\n}\n.nav-links a.btn-nav {\n  background: var(--black);\n  color: var(--cream);\n  padding: 10px 18px;\n  border-radius: 999px;\n  font-size: 14px;\n}\n\n/* ===== Buttons ===== */\n.btn-primary, .btn-secondary {\n  display: inline-flex;\n  align-items: center;\n  gap: 8px;\n  font-weight: 700;\n  padding: 14px 26px;\n  border-radius: 999px;\n  font-size: 15px;\n  transition: transform 0.15s ease;\n}\n.btn-primary {\n  background: var(--yellow);\n  color: var(--black);\n  border: 2px solid var(--black);\n}\n.btn-secondary {\n  background: transparent;\n  color: var(--black);\n  border: 2px solid var(--black);\n}\n.btn-primary:hover, .btn-secondary:hover { transform: translateY(-2px); }\n\n/* ===== Hero ===== */\n.hero {\n  display: grid;\n  grid-template-columns: 1.1fr 0.9fr;\n  gap: 48px;\n  align-items: center;\n  padding: 56px 0 96px;\n}\n.eyebrow {\n  display: inline-block;\n  background: var(--white);\n  border: 1px solid var(--border);\n  padding: 6px 14px;\n  border-radius: 999px;\n  font-size: 13px;\n  font-weight: 700;\n  text-transform: uppercase;\n  letter-spacing: 0.06em;\n  margin-bottom: 18px;\n}\n.hero h1 {\n  font-size: clamp(38px, 5vw, 58px);\n  line-height: 1.08;\n}\n.hero h1 .highlight {\n  background: var(--yellow);\n  padding: 0 8px;\n  border-radius: 8px;\n  display: inline-block;\n}\n.hero-sub {\n  margin-top: 22px;\n  font-size: 18px;\n  color: var(--muted);\n  max-width: 520px;\n}\n.hero-actions {\n  display: flex;\n  gap: 16px;\n  margin-top: 34px;\n  flex-wrap: wrap;\n}\n\n.hero-visual {\n  position: relative;\n  height: 420px;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n}\n.hero-visual::before {\n  content: \"\";\n  position: absolute;\n  width: 320px;\n  height: 320px;\n  border-radius: 50%;\n  background: var(--yellow);\n  top: 50%;\n  left: 50%;\n  transform: translate(-46%, -52%);\n  z-index: 0;\n}\n.photo-frame {\n  position: relative;\n  z-index: 1;\n  width: 300px;\n  height: 300px;\n  border-radius: 50%;\n  overflow: hidden;\n  border: 4px solid var(--black);\n  box-shadow: var(--shadow);\n  background: var(--white);\n}\n.photo-frame .hero-photo {\n  width: 100%;\n  height: 100%;\n  object-fit: cover;\n}\n.photo-placeholder {\n  display: none;\n  width: 100%;\n  height: 100%;\n  flex-direction: column;\n  align-items: center;\n  justify-content: center;\n  gap: 10px;\n  text-align: center;\n  font-size: 34px;\n  color: var(--muted);\n  padding: 20px;\n}\n.photo-placeholder span {\n  font-size: 12px;\n  font-weight: 600;\n  line-height: 1.5;\n}\n.photo-placeholder code {\n  font-size: 11px;\n  background: var(--cream-2);\n  padding: 2px 6px;\n  border-radius: 6px;\n}\n.spark {\n  position: absolute;\n  font-size: 34px;\n  z-index: 1;\n}\n.spark-1 { top: 10px; right: 40px; }\n.spark-2 { bottom: 20px; left: 30px; }\n\n/* ===== About ===== */\n.about {\n  padding: 64px 0;\n  border-top: 2px solid var(--black);\n}\n.about h2 {\n  font-size: 34px;\n  max-width: 900px;\n  margin-bottom: 32px;\n}\n.about-bio {\n  display: flex;\n  flex-direction: column;\n  gap: 24px;\n  max-width: 980px;\n}\n.about p.bio {\n  color: var(--muted);\n  font-size: 19px;\n  line-height: 1.75;\n}\n/* ===== Highlights ===== */\n.highlights {\n  padding: 64px 0;\n  border-top: 2px solid var(--black);\n}\n.highlights h2 {\n  font-size: 32px;\n  margin-bottom: 32px;\n}\n.highlight-grid {\n  display: grid;\n  grid-template-columns: repeat(3, 1fr);\n  gap: 20px;\n  margin-bottom: 36px;\n}\n.highlight-card {\n  background: var(--white);\n  border: 2px solid var(--black);\n  border-radius: var(--radius);\n  padding: 24px;\n  display: flex;\n  flex-direction: column;\n  min-height: 336px;\n}\n.hl-tag {\n  font-size: 19px;\n  font-weight: 700;\n  font-family: 'Baloo 2', sans-serif;\n  margin-bottom: 12px;\n}\n.hl-desc {\n  font-size: 14px;\n  color: var(--black);\n  line-height: 1.5;\n  margin-bottom: 16px;\n}\n.hl-metrics {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 8px;\n  margin-top: auto;\n}\n.hl-metric {\n  display: inline-block;\n  background: var(--yellow);\n  border: 2px solid var(--black);\n  border-radius: 999px;\n  padding: 6px 14px;\n  font-family: 'Baloo 2', sans-serif;\n  font-weight: 700;\n  font-size: 15px;\n}\n\n/* ===== Social proof ===== */\n.social-proof {\n  padding: 64px 0;\n  border-top: 2px solid var(--black);\n  text-align: center;\n}\n.social-proof h2 { font-size: 32px; margin-bottom: 14px; }\n.social-proof p { color: var(--muted); font-size: 17px; margin-bottom: 28px; }\n.linkedin-btn { background: var(--black); color: var(--cream); border-color: var(--black); }\n\n/* ===== Footer ===== */\n.footer {\n  border-top: 2px solid var(--black);\n  padding: 40px 0 32px;\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  flex-wrap: wrap;\n  gap: 16px;\n}\n.footer-name {\n  font-family: 'Baloo 2', sans-serif;\n  font-weight: 700;\n  font-size: 18px;\n}\n.footer p { font-size: 14px; color: var(--muted); }\n.footer-links { display: flex; gap: 22px; font-weight: 600; }\n.footer-copy { width: 100%; margin-top: 20px; font-size: 13px; color: var(--muted); }\n\n/* ===== Responsive ===== */\n@media (max-width: 860px) {\n  .hero { grid-template-columns: 1fr; }\n  .hero-visual { height: 280px; margin-top: 20px; }\n  .about p.bio { font-size: 17px; }\n  .highlight-grid { grid-template-columns: 1fr 1fr; }\n  .nav-links { gap: 14px; font-size: 13px; }\n}\n@media (max-width: 520px) {\n  .highlight-grid { grid-template-columns: 1fr; }\n  .wrap, .nav { padding-left: 20px; padding-right: 20px; }\n}\n";
