function sliderMarkup(title) {
  const content = sliderContent[title];
  const slides = content.images.map(function (src, index) {
    return `<div class="slider-slide" role="group" aria-label="Image ${index + 1} of ${content.images.length}">
                <img src="${src}" alt="${content.labels[index]}" loading="lazy">
              </div>`;
  }).join('');
  const dots = Array.from({ length: content.images.length }, function (_, index) {
    return `<button class="slider-dot" type="button" data-slide="${index}" aria-label="Show image ${index + 1}"></button>`;
  }).join('');

  return `<div class="project-slider" data-slider tabindex="0" aria-label="${title} image slider">
          <div class="slider-viewport">
            <div class="slider-track">${slides}</div>
          </div>
          <div class="slider-controls">
            <button class="slider-arrow" type="button" data-prev aria-label="Previous image">←</button>
            <div class="slider-dots" aria-label="Choose image">${dots}</div>
            <button class="slider-arrow" type="button" data-next aria-label="Next image">→</button>
          </div>
        </div>`;
}

const sliderScript = `<script>
document.querySelectorAll('[data-slider]').forEach(function (slider) {
  var track = slider.querySelector('.slider-track');
  var slides = Array.from(slider.querySelectorAll('.slider-slide'));
  var dots = Array.from(slider.querySelectorAll('.slider-dot'));
  var current = 0;

  function showSlide(next) {
    current = (next + slides.length) % slides.length;
    track.style.transform = 'translateX(-' + (current * 100) + '%)';
    dots.forEach(function (dot, index) {
      dot.classList.toggle('is-active', index === current);
      dot.setAttribute('aria-current', index === current ? 'true' : 'false');
    });
  }

  slider.querySelector('[data-prev]').addEventListener('click', function () {
    showSlide(current - 1);
  });
  slider.querySelector('[data-next]').addEventListener('click', function () {
    showSlide(current + 1);
  });
  dots.forEach(function (dot, index) {
    dot.addEventListener('click', function () { showSlide(index); });
  });
  slider.addEventListener('keydown', function (event) {
    if (event.key === 'ArrowLeft') showSlide(current - 1);
    if (event.key === 'ArrowRight') showSlide(current + 1);
  });

  showSlide(0);
});
</script>`;

